#include <stdio.h>
#include <stdlib.h>

int main(int argc, char **argv) {
    if (argc < 2) {
        puts("NO_INPUT");
        return 0;
    }
    char *endptr = NULL;
    long n = strtol(argv[1], &endptr, 10);
    if (endptr == argv[1] || *endptr != '\0') {
        puts("BAD_INPUT");
        return 0;
    }
    if (n < 0) {
        puts("BAD_INPUT");
        return 0;
    }
    if (n == 0) {
        puts("EMPTY");
        return 0;
    }
    if (n > 60) { // limit to avoid overflow of 64-bit values
        puts("OUT_OF_RANGE");
        return 0;
    }
    long row[61] = {0};
    row[0] = 1;
    for (int i = 0; i <= n; ++i) {
        // print current row
        for (int j = 0; j <= i; ++j) {
            if (j) putchar(' ');
            printf("%lld", row[j]);
        }
        putchar('\n');
        // compute next row in-place (right to left)
        for (int j = i + 1; j > 0; --j) {
            if (j == i + 1) {
                row[j] = 1;
            } else if (j == 0) {
                row[j] = 1;
            } else {
                row[j] = row[j] + row[j - 1];
            }
        }
    }
    return 0;
}
